body.onloadscript:

gridObj.enableMultiline(true);

gridObj.setDragBehavior("complex");

gridObj.attachEvent("onEditCell", function(stage, rowId, cellInd, nValue, oValue) {
    var useYnInd = gridObj.getColIndexById("USE_YN");
    var treeParentIdIdx = gridObj.getColIndexById("TREE_PARENT_ID");
    var treeIdIdx = gridObj.getColIndexById("TREE_ID");
    if (stage == 0) {
        if (useYnInd != cellInd && gridObj.isReadOnly) {
            return false;
        }
    } else if (stage == 1) {
        if (useYnInd == cellInd) {
            var useYn = gridObj.cells(rowId, useYnInd).getValue();
            var treeParentId = gridObj.cells(rowId, treeParentIdIdx).getValue();
            if (treeParentId == "*") {
                var treeId = gridObj.cells(rowId, treeIdIdx).getValue();
                var rowsNum = gridObj.getRowsNum();
                for (var i = 0; i < rowsNum; i++) {
                    var rowId = gridObj.getRowId(i);
                    var parentId = gridObj.cells(rowId, treeParentIdIdx).getValue();
                    if (parentId == treeId) {
                        gridObj.cells(rowId, useYnInd).setValue(useYn);
                        gridObj.cells(rowId, useYnInd).cell.wasChanged = true;
                    }
                }
            } else {
                var rowsNum = gridObj.getRowsNum();
                var pId = gridObj.cells(rowId, treeParentIdIdx).getValue();
                var anyUseY = false;
                var allUseN = true;
                var parentRowId;
                for (var i = 0; i < rowsNum; i++) {
                    var cRowId = gridObj.getRowId(i);
                    var treeParentId = gridObj.cells(cRowId, treeParentIdIdx).getValue();
                    if (treeParentId == pId) {
                        var useYn = gridObj.cells(cRowId, useYnInd).getValue();
                        if (useYn == '1') {
                            anyUseY = true;
                            allUseN = false;
                        }
                    }
                    if (gridObj.cells(cRowId, treeIdIdx).getValue() == pId) {
                        parentRowId = cRowId;
                    }
                }

                if (anyUseY) {
                    gridObj.cells(parentRowId, useYnInd).setValue('1');
                    gridObj.cells(parentRowId, useYnInd).cell.wasChanged = true;
                }
                if (allUseN) {
                    gridObj.cells(parentRowId, useYnInd).setValue('0');
                    gridObj.cells(parentRowId, useYnInd).cell.wasChanged = true;
                }
            }
        }
    }
    return true;
});
gridObj.setReadOnly = function(b) {
    gridObj.isReadOnly = b;
}



