userscript.function:

var msg = obj.getUserData("", "message");
var status = obj.getUserData("", "status");
if (status != "true") {
    Alert(msg);
} else {
    var sf = new SepoaFormater(obj.getUserData("", "headerData"));
    if (sf.getRowCount() > 0) {
        formObj.dataMapper(sf);
        changeMode('VIEW');
    } else {
        changeMode('CLEAR');
    }
    gridObj.expandAll();
    order();
}


if (mode == 'VIEW') {
    changeMode('CLEAR');
    btnObj.showButton('update', true);
    btnObj.showButton('delete', true);
    btnObj.showButton('new', true);

    formObj.setViewMode(true);
    gridObj.setReadOnly(true);
} else if (mode == 'INSERT') {
    changeMode('CLEAR');
    btnObj.showButton('save', true);
    btnObj.showButton('cancel', true);
    btnObj.showButton('execute', false);
    btnObj.showButton('addRow', true);
    btnObj.showButton('deleteRow', true);
    formObj.setViewMode(false);
    gridObj.setReadOnly(false);
} else if (mode == 'CLEAR') {
    btnObj.showButton('update', false);
    btnObj.showButton('delete', false);
    btnObj.showButton('new', false);
    btnObj.showButton('save', false);
    btnObj.showButton('cancel', false);

    btnObj.showButton('execute', true);
    btnObj.showButton('addRow', false);
    btnObj.showButton('deleteRow', false);
    formObj.setViewMode(false);
    gridObj.setReadOnly(false);
}
