var pOrder = 0;
var cOrder = 0;
var treeParentIdIdx = gridObj.getColIndexById("TREE_PARENT_ID");
var orderIdx = gridObj.getColIndexById("ORDER");
var seqIdx = gridObj.getColIndexById("SEQ");
var rowsNum = gridObj.getRowsNum();
for (var i = 0; i < rowsNum; i++) {
    var cRowId = gridObj.getRowId(i);
    var treeParentId = gridObj.cells(cRowId, treeParentIdIdx).getValue();
    if (treeParentId == "*") {
        gridObj.cells(cRowId, orderIdx).setValue("" + (++pOrder));
        gridObj.cells(cRowId, seqIdx).setValue("0");
        cOrder = 0;
    } else {
        gridObj.cells(cRowId, orderIdx).setValue("" + pOrder);
        gridObj.cells(cRowId, seqIdx).setValue("" + (++cOrder));
    }
}


